 431	async function createEntityWithIdentities(
 432	  sql: DbClient,
 433	  params: {
 434	    orgId: string;
 435	    connectorKey: string;
 436	    connectionId?: number | null;
 437	    entityType: string;
 438	    title: string;
 439	    identities: ExtractedLink['identities'];
 440	    traits: Map<string, unknown>;
 441	    creatorUserId: string;
 442	  }
 443	): Promise<{ entityId: number; attached: Array<{ namespace: string; identifier: string }> } | null> {
 444	  const persisted = params.identities.filter((i) => !i.matchOnly);
 445	  if (persisted.length === 0) return null;
 446	
 447	  const name = params.title || persisted[0].identifier;
 448	  const metadata: Record<string, unknown> = {};
 449	  for (const [key, value] of params.traits) metadata[key] = value;
 450	
 451	  // Resolve entity_type slug → entity_types(id). Same schema search path as
 452	  // createEntity: try the entity's own org first, then any visibility='public'
 453	  // catalog. First match wins. See createEntity for the slug-poisoning caveat.
 454	  let typeRow = await sql<{ id: number; backing_sql: string | null }>`
 455	    SELECT et.id, et.backing_sql
 456	    FROM entity_types et
 457	    LEFT JOIN organization o ON o.id = et.organization_id
 458	    WHERE et.slug = ${params.entityType}
 459	      AND et.deleted_at IS NULL
 460	      AND (
 461	        et.organization_id = ${params.orgId}
 462	        OR o.visibility = 'public'
 463	      )
 464	    ORDER BY (et.organization_id = ${params.orgId}) DESC, et.id ASC
 465	    LIMIT 1
 466	  `;
 467	  if (typeRow.length === 0) {
 468	    // Platform ACL type is ensured on the fly so event attribution can race
 469	    // ahead of the first ACL sync without failing closed on a missing type.
 470	    if (params.entityType === ACL_RESOURCE_TYPE_SLUG) {
 471	      await ensureResourceEntityType(params.orgId);
 472	      typeRow = await sql<{ id: number; backing_sql: string | null }>`
 473	        SELECT et.id, et.backing_sql
 474	        FROM entity_types et
 475	        WHERE et.slug = ${params.entityType}
 476	          AND et.deleted_at IS NULL
 477	          AND et.organization_id = ${params.orgId}
 478	        LIMIT 1
 479	      `;
 480	      if (typeRow.length === 0) {
 481	        logger.warn(
 482	          { entityType: params.entityType, orgId: params.orgId },
 483	          'entity create failed: $resource type ensure did not materialize'
 484	        );
 485	        return null;
 486	      }
 487	    } else {
 488	      logger.warn(
 489	        { entityType: params.entityType, orgId: params.orgId },
