 501	      'entity auto-create skipped: entity type is derived (a SQL view)'
 502	    );
 503	    return null;
 504	  }
 505	  const entityTypeId = typeRow[0].id;
 506	
 507	  // Try a few slug variants to defuse improbable random collisions.
 508	  let entityId: number | null = null;
 509	  for (let attempt = 0; attempt < 3 && entityId === null; attempt++) {
