 544	/**
 545	 * Insert identities for `entityId`, RETURNING the `(namespace, identifier)` rows
 546	 * attached to that entity. Re-observing a legacy row fills missing connection
 547	 * provenance; a row owned by another entity is not returned, so the caller will
 548	 * not mis-claim it.
 549	 */
 550	async function insertIdentities(
 551	  sql: DbClient,
 552	  params: {
 553	    orgId: string;
 554	    entityId: number;
 555	    connectorKey: string;
 556	    connectionId?: number | null;
 557	    identities: ExtractedLink['identities'];
 558	  }
 559	): Promise<Array<{ namespace: string; identifier: string }>> {
 560	  if (params.identities.length === 0) return [];
 561	  const namespaces = params.identities.map((i) => i.namespace);
 562	  const identifiers = params.identities.map((i) => i.identifier);
 563	  const attached = await sql<{ namespace: string; identifier: string }>`
 564	    INSERT INTO entity_identities (
 565	      organization_id, entity_id, namespace, identifier, source_connector, connection_id
 566	    )
 567	    SELECT ${params.orgId}, ${params.entityId}, v.ns, v.ident,
 568	           ${`connector:${params.connectorKey}`}, ${params.connectionId ?? null}
 569	    FROM unnest(${pgTextArray(namespaces)}::text[], ${pgTextArray(identifiers)}::text[]) AS v(ns, ident)
 570	    ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
 571	    DO UPDATE SET connection_id = EXCLUDED.connection_id
 572	    WHERE entity_identities.entity_id = EXCLUDED.entity_id
 573	      AND entity_identities.connection_id IS NULL
 574	      AND EXCLUDED.connection_id IS NOT NULL
 575	    RETURNING namespace, identifier
 576	  `;
 577	  return attached.map((r) => ({ namespace: r.namespace, identifier: r.identifier }));
 578	}
