 580	async function applyTraits(
 581	  sql: DbClient,
 582	  params: {
 583	    orgId: string;
 584	    entityId: number;
 585	    rule: ResolvedEventAttributionRule;
 586	    traits: Map<string, unknown>;
 587	    isCreate: boolean;
 588	  }
 589	): Promise<void> {
 590	  if (!params.rule.traits || params.traits.size === 0) return;
 591	
 592	  // init_only traits were written to metadata at create time; nothing to do now.
 593	  const overwrite: Record<string, unknown> = {};
 594	  const preferNonEmpty: Record<string, unknown> = {};
 595	  for (const [key, value] of params.traits) {
 596	    const spec = params.rule.traits[key];
 597	    if (!spec || spec.mergeStrategy === 'init_only') continue;
 598	    if (value === undefined) continue;
 599	    if (spec.mergeStrategy === 'overwrite') {
 600	      overwrite[key] = value;
 601	    } else if (spec.mergeStrategy === 'prefer_non_empty') {
 602	      const empty = value === null || value === '';
 603	      if (!empty) preferNonEmpty[key] = value;
 604	    }
 605	  }
 606	  if (Object.keys(overwrite).length === 0 && Object.keys(preferNonEmpty).length === 0) return;
 607	
 608	  // Serialize the metadata read-modify-write with alias and trait projections
 609	  // from concurrent connector transactions.
 610	  const rows = await sql<{ metadata: Record<string, unknown> | null }>`
 611	    SELECT metadata
 612	    FROM entities
 613	    WHERE id = ${params.entityId}
 614	      AND organization_id = ${params.orgId}
 615	      AND deleted_at IS NULL
 616	    FOR UPDATE
 617	  `;
 618	  if (rows.length === 0) return;
 619	  const current = rows[0].metadata ?? {};
 620	
 621	  const next: Record<string, unknown> = { ...current, ...overwrite };
 622	  for (const [key, value] of Object.entries(preferNonEmpty)) {
 623	    const existing = current[key];
 624	    if (existing === undefined || existing === null || existing === '') {
 625	      next[key] = value;
 626	    }
 627	  }
 628	
 629	  await patchEntityRows({
 630	    tx: sql,
 631	    ids: [params.entityId],
