   325	    | {
   326	        connector_key: string | null;
   327	        connection_id: number | string | null;
   328	        feed_key: string | null;
   329	        feed_id: number | string | null;
   330	        run_id: number | string | null;
   331	        automation_id: number | string | null;
   332	        automation_version_id: number | string | null;
   333	        origin_parent_id: string | null;
