   344	    connectorKey: prior.connector_key ?? null,
   345	    connectionId: nullableNumber(prior.connection_id),
   346	    feedKey: prior.feed_key ?? null,
   347	    feedId: nullableNumber(prior.feed_id),
   348	    runId: params.runId ?? nullableNumber(prior.run_id),
   349	    automationId: params.automationId ?? nullableNumber(prior.automation_id),
