   358	function isEventsClientIdForeignKeyViolation(error: unknown): boolean {
   359	  const err = error as {
   360	    code?: unknown;
   361	    constraint?: unknown;
   362	    constraint_name?: unknown;
   363	    message?: unknown;
   364	  };
   365	  if (err?.code !== '23503') return false;
   366	  return (
   367	    err.constraint === 'events_client_id_fkey' ||
   368	    err.constraint_name === 'events_client_id_fkey' ||
   369	    (typeof err.message === 'string' && err.message.includes('events_client_id_fkey'))
   370	  );
   371	}
