   373	/**
   374	 * Insert a single event into the events table.
   375	 *
   376	 * Returns the inserted row (id, entity_ids, title, semantic_type, created_at).
   377	 * If `onConflictUpdate` is true, performs an upsert on (connection_id, origin_id).
   378	 * If `sql` is passed, the insert runs on that (transaction-bound) handle
   379	 * instead of the singleton pool — used by the identity engine to keep its
   380	 * fact + derivation writes atomic.
   381	 */
   382	export async function insertEvent(
   383	  params: InsertEventParams,
   384	  options?: {
   385	    onConflictUpdate?: boolean;
   386	    sql?: DbClient;
   387	    /** Transactional hook for durable derived work such as Automation runs. */
   388	    afterPersist?: (event: InsertedEvent, sql: DbClient) => Promise<void>;
   389	  }
   390	): Promise<InsertedEvent> {
   391	  const sql = options?.sql ?? getDb();
   392	
   393	  // Reverse-geocode lat/lng → city / admin1 / country once per event,
   394	  // before insert. Silent no-op when the connector hasn't supplied
   395	  // coordinates, when PostGIS / geo_places aren't seeded, or when the
   396	  // nearest place is too far (ocean / desert). Connector-supplied
   397	  // place_name etc. are preserved — enrichment only fills gaps.
   398	  const enrichment = await lookupGeoEnrichment(params.metadata, { sql });
   399	  const enrichedMetadata = mergeEnrichedMetadata(params.metadata, enrichment);
   400	  if (enrichedMetadata !== params.metadata) {
   401	    params = { ...params, metadata: enrichedMetadata };
   402	  }
   403	
   404	  const entityIdsValue = params.entityIds.length > 0 ? `{${params.entityIds.join(',')}}` : null;
   405	
   406	  const requestedClientId = params.clientId ?? null;
   407	
   408	  // Core find→decide→insert, parameterized on the active SQL handle so it can
   409	  // run either directly on the singleton pool or inside the dedup transaction
   410	  // below (which holds an advisory lock for the duration).
   411	  const runInsert = async (
   412	    activeSql: DbClient
   413	  ): Promise<InsertedEvent> => {
   414	    let supersedesEventId = params.supersedesEventId ?? null;
   415	
   416	    if (options?.onConflictUpdate) {
   417	      const existing = await findCurrentEventByOrigin(activeSql, params);
   418	      if (existing) {
   419	        if (isSemanticallyEqual(existing, params)) {
   420	          // Reread before touching the embedding. If the row got
   421	          // deleted / tombstoned between findCurrentEventByOrigin and
   422	          // here, upsertEmbedding would FK-fail instead of letting us
   423	          // fall through cleanly to a fresh insert (CodeRabbit catch
   424	          // on PR #780).
   425	          const existingRows = await activeSql`
   426	            SELECT id, entity_ids, origin_id, title, semantic_type, created_at
   427	            FROM events
   428	            WHERE id = ${existing.id}
   429	            LIMIT 1
   430	          `;
   431	          const existingRow = existingRows[0] as InsertedEvent | undefined;
   432	          if (existingRow) {
   433	            await upsertEmbedding(
   434	              existingRow.id,
   435	              params.embedding,
   436	              params.embeddingModel,
   437	              activeSql
   438	            );
   439	            const unchanged = { ...existingRow, change: 'unchanged' as const };
   440	            await options?.afterPersist?.(unchanged, activeSql);
   441	            return unchanged;
   442	          }
   443	          // Race: the existing row was deleted/tombstoned between the
   444	          // findCurrentEventByOrigin lookup above and the SELECT here. Fall
   445	          // through into the INSERT path with `supersedesEventId` unset so we
   446	          // create a fresh row instead of crashing on `undefined.id`.
   447	          logger.warn(
   448	            { existingId: existing.id, originId: params.originId },
   449	            '[insert-event] existing row vanished between find and reread — proceeding with fresh insert'
   450	          );
   451	        } else {
   452	          supersedesEventId = existing.id;
   453	        }
   454	      }
   455	    }
   456	
   457	    return insertRow(activeSql, supersedesEventId);
   458	  };
   459	
   460	  const insertRow = async (
   461	    sql: DbClient,
   462	    supersedesEventId: number | null
   463	  ): Promise<InsertedEvent> => {
   464	    const lineage: EventLineage =
   465	      supersedesEventId != null
   466	        ? await loadEventLineage(sql, supersedesEventId, params)
   467	        : {
   468	            connectorKey: params.connectorKey ?? null,
   469	            connectionId: params.connectionId ?? null,
   470	            feedKey: params.feedKey ?? null,
   471	            feedId: params.feedId ?? null,
   472	            runId: params.runId ?? null,
   473	            automationId: params.automationId ?? null,
   474	            automationVersionId: params.automationVersionId ?? null,
   475	            parentOriginId: params.parentOriginId ?? null,
   476	            identityNs: params.identity?.ns ?? null,
   477	            identityKey: params.identity?.key ?? null,
   478	          };
   479	
   480	    const insertWithClientId = (activeSql: DbClient, clientId: string | null) => activeSql`
   481	    INSERT INTO events (
   482	      entity_ids, organization_id, origin_id, title,
   483	      payload_type, payload_text, payload_data, payload_template, attachments, metadata,
   484	      score, author_name, source_url, occurred_at, origin_parent_id, origin_type,
   485	      connector_key, connection_id, feed_key, feed_id, run_id,
   486	      automation_id, automation_version_id,
   487	      semantic_type, client_id, created_by,
   488	      interaction_type, interaction_status, interaction_input_schema, interaction_input,
   489	      interaction_output, interaction_error, supersedes_event_id,
   490	      identity_ns, identity_key,
   491	      linked_org_ids
   492	    ) VALUES (
   493	      ${entityIdsValue}::bigint[],
   494	      ${params.organizationId},
   495	      ${params.originId},
   496	      ${params.title ?? null},
   497	      ${params.payloadType ?? 'text'},
   498	      ${params.content ?? null},
   499	      ${sql.json(params.payloadData ?? {})},
   500	      ${params.payloadTemplate ? sql.json(params.payloadTemplate) : null},
   501	      ${sql.json(params.attachments ?? [])},
   502	      ${sql.json(params.metadata ?? {})},
   503	      ${params.score ?? null},
   504	      ${params.authorName ?? null},
   505	      ${params.sourceUrl ?? null},
   506	      ${params.occurredAt ?? new Date()},
   507	      ${lineage.parentOriginId},
   508	      ${params.originType ?? null},
   509	      ${lineage.connectorKey},
   510	      ${lineage.connectionId},
   511	      ${lineage.feedKey},
   512	      ${lineage.feedId},
   513	      ${lineage.runId},
   514	      ${lineage.automationId},
   515	      ${lineage.automationVersionId},
   516	      ${params.semanticType},
   517	      ${clientId},
   518	      ${params.createdBy ?? null},
   519	      ${params.interactionType ?? 'none'},
   520	      ${params.interactionStatus ?? null},
   520	      ${params.interactionStatus ?? null},
   521	      ${params.interactionInputSchema ? sql.json(params.interactionInputSchema) : null},
   522	      ${params.interactionInput ? sql.json(params.interactionInput) : null},
   523	      ${params.interactionOutput ? sql.json(params.interactionOutput) : null},
   524	      ${params.interactionError ?? null},
   525	      ${supersedesEventId},
   526	      ${lineage.identityNs},
   527	      ${lineage.identityKey},
   528	      (
   529	        SELECT COALESCE(array_agg(DISTINCT x.o), '{}'::text[])
   530	        FROM (
   531	          SELECT ent.organization_id AS o
   532	          FROM public.entities ent
   533	          WHERE ent.id = ANY(${entityIdsValue}::bigint[])
   534	          UNION ALL
   535	          SELECT c.organization_id AS o
   536	          FROM public.connections c
   537	          WHERE c.id = ${lineage.connectionId}
   538	        ) x
   539	        WHERE x.o IS NOT NULL
   540	          AND (x.o <> ${params.organizationId}::text OR ${params.organizationId}::text IS NULL)
   541	      )
   542	    )
   543	    RETURNING id, entity_ids, origin_id, title, semantic_type, created_at
   544	  `;
   545	
   546	  // A synthetic or stale client id (worker/PAT sessions carry `'lobu-worker'`,
   547	  // which has no oauth_clients row) trips `events_client_id_fkey`. The retry
   548	  // must survive the enclosing transaction: the supersede path runs inside
   549	  // `sql.begin`, and a bare failed INSERT aborts the whole transaction — the
   550	  // NULL retry would then die on `current transaction is aborted`. Wrapping
   551	  // the first attempt in a savepoint (only available on tx handles) rolls
   552	  // back cleanly so the NULL retry runs against a live transaction. On the
   553	  // plain pool handle there is no transaction to abort, so no savepoint is
   554	  // needed.
   555	  let result: Awaited<ReturnType<typeof insertWithClientId>>;
   556	  const inTransaction = typeof sql.savepoint === 'function';
   557	  try {
   558	    result = inTransaction
   559	      ? await sql.savepoint((sp) => insertWithClientId(sp, requestedClientId))
   560	      : await insertWithClientId(sql, requestedClientId);
   561	  } catch (error) {
   562	    if (!requestedClientId || !isEventsClientIdForeignKeyViolation(error)) {
   563	      throw error;
   564	    }
   565	    logger.warn(
   566	      { clientId: requestedClientId },
   567	      '[insert-event] retrying insert with client_id NULL — referenced oauth_clients row no longer exists'
   568	    );
   569	    result = await insertWithClientId(sql, null);
   570	  }
   571	
   572	  const inserted = result[0] as InsertedEvent | undefined;
   573	  if (!inserted) {
   574	    // INSERT ... RETURNING should always yield a row for a successful insert.
   575	    // An empty result means either (a) a BEFORE INSERT trigger silently
   576	    // RETURNed NULL (none in our schema today), or (b) postgres.js dropping
   577	    // the rows for an obscure reason. Neither should drop events on the
   578	    // floor — convert the cryptic `Cannot read
   579	    // properties of undefined (reading 'id')` into a real error with
   580	    // diagnostic context so we can root-cause when it next happens.
   581	    logger.error(
   582	      {
   583	        originId: params.originId,
   584	        connectionId: params.connectionId,
   585	        organizationId: params.organizationId,
   586	        semanticType: params.semanticType,
   587	        connectorKey: params.connectorKey,
   588	        feedKey: params.feedKey,
   589	      },
   590	      '[insert-event] INSERT ... RETURNING returned no rows — event not persisted'
   591	    );
   592	    throw new Error(
   593	      `insertEvent: INSERT RETURNING came back empty for ` +
   594	        `origin_id=${params.originId} connection_id=${params.connectionId}. ` +
   595	        `Row was not persisted; check server logs for diagnostic context.`
   596	    );
   597	  }
   598	
   599	    // Dual-write the denormalized supersession edge. `events.superseded_by`
   600	    // holds the inverse of `supersedes_event_id`: we stamp the row we just
   601	    // replaced with the id of THIS new superseding row so live-row reads can
   602	    // one day use `WHERE superseded_by IS NULL` instead of the per-row
   603	    // anti-join in current_event_records. This touches LINEAGE METADATA ONLY,
   604	    // never payload — the append-only invariant applies to content (precedent:
   605	    // search_tsv is likewise maintained post-insert). Runs on the SAME `sql`
   606	    // handle as the INSERT, so when we're inside the dedup advisory-lock tx or
   607	    // a caller-supplied tx (identity engine) it is atomic with the supersede.
   608	    //
   609	    // The `AND superseded_by IS NULL` guard is belt-and-braces: the partial
   610	    // unique index idx_events_superseded_by already fired a 23505 on the INSERT
   611	    // above if the target was already superseded, so a 0-row UPDATE here can
   612	    // only happen if the column was backfilled/stamped by a losing concurrent
   613	    // writer whose INSERT nonetheless slipped through — in which case leaving
   614	    // the existing stamp intact is correct (the unique index still guarantees a
   615	    // single superseder).
   616	    if (supersedesEventId !== null) {
   617	      await sql`
   618	        UPDATE events
   619	        SET superseded_by = ${inserted.id}
   620	        WHERE id = ${supersedesEventId}
   621	          AND superseded_by IS NULL
   622	      `;
   623	    }
   624	
   625	    await upsertEmbedding(inserted.id, params.embedding, params.embeddingModel, sql);
   626	    const persisted: InsertedEvent = {
   627	      ...inserted,
   628	      change: supersedesEventId === null ? 'inserted' : 'superseded',
   629	    };
   630	    await options?.afterPersist?.(persisted, sql);
   631	    return persisted;
   632	  };
   633	
   634	  // The dedup path (onConflictUpdate) is a non-atomic read-then-insert: it
   635	  // looks up the current row for (connection_id, origin_id), then either
   636	  // supersedes it or inserts fresh. Without serialization, two concurrent
   637	  // ingests of the SAME item — common under N>1 app replicas and even two
   638	  // overlapping runs on one replica — can both see "no current row" and both
   639	  // insert with supersedes_event_id NULL (→ permanent duplicate current rows),
   640	  // or both target the same row to supersede (→ duplicate-key error on
   641	  // idx_events_superseded_by, which fails the whole stream batch). Hold a
   642	  // transaction-scoped advisory lock keyed on (connection_id, origin_id) so
   643	  // these serialize. Only engage when we own the connection (no caller-supplied
   644	  // tx, which already runs in its own atomic scope) and have both keys.
   645	  if (options?.onConflictUpdate && !options.sql && params.connectionId && params.originId) {
   646	    const lockKey = eventDedupLockKey(params.connectionId, params.originId);
   647	    return sql.begin(async (tx) => {
   648	      await tx`
   649	        SELECT pg_advisory_xact_lock(${EVENT_DEDUP_LOCK_NAMESPACE}, ${lockKey})
   650	      `;
   651	      return runInsert(tx);
   652	    }) as Promise<InsertedEvent>;
   653	  }
   654	
   655	  // An explicit supersede without a caller-supplied tx must still commit the
   656	  // superseding INSERT and the superseded_by stamp atomically: as two
   657	  // autocommit statements, a crash between them would leave the superseded
   658	  // row's denormalized edge permanently NULL — which, after the Stage-2 view
   659	  // flip to `WHERE superseded_by IS NULL`, would resurrect it as a live row.
   660	  // (The dedup path can only derive a supersede when connectionId+originId are
   661	  // both present, and that case is already inside the advisory-lock tx above.)
   662	  if (params.supersedesEventId != null && !options?.sql) {
   663	    return sql.begin(async (tx) =>
   664	      runInsert(tx)
   665	    ) as Promise<InsertedEvent>;
   666	  }
   667	
   668	  return runInsert(sql);
   669	}
