   745	/**
   746	 * Record a change event for audit purposes.
   747	 *
   748	 * Fire-and-forget — never throws. Retries once after a short delay; the same
   749	 * originId is reconciled before re-insert so an ambiguous success cannot
   750	 * append a duplicate. If both attempts fail the dropped audit row is logged
   751	 * at ERROR with full event context so it's visible in alerting rather than
   752	 * silently lost. Used for entity updates, automation archival, connection/feed
   753	 * deletion, etc.
   754	 */
   755	export function recordChangeEvent(params: ChangeEventParams): void {
   756	  if (params.entityIds.length === 0) return;
   757	
   758	  const externalId = `change_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
   759	
   760	  retryWithBackoff(
   780	        entityIds: params.entityIds,
   781	        title: params.title,
   782	        metadata: params.metadata,
   783	      },
   784	      '[insert-event] change audit event DROPPED after retry — audit trail is missing this row'
   785	    );
   786	  });
   787	}
