   789	interface EdgeFieldChange {
   790	  field: string;
   791	  old: unknown;
   792	  new: unknown;
   793	}
   794	
   795	interface EdgeChangeEventParams {
   796	  organizationId: string;
   797	  relationshipId: number;
   798	  fromEntityId: number;
   799	  toEntityId: number;
   800	  relationshipTypeId: number;
   801	  relationshipTypeSlug: string | null;
   802	  op: 'link' | 'unlink' | 'update_link';
   803	  changes: EdgeFieldChange[];
   804	  createdBy?: string | null;
   805	  clientId?: string | null;
   806	}
   807	
   808	/**
   809	 * Record a relationship (edge) change for audit.
   810	 *
   811	 * Fire-and-forget with the same retry-then-log-and-drop contract as
   812	 * `recordChangeEvent`, and for the same reason: `entity_relationships` remains
   813	 * the source of truth for what is currently linked, so a dropped row costs
   814	 * history, never state.
   815	 *
   816	 * Metadata shape (all ids stringified so `metadata->>'...'` comparisons work):
   817	 *   {
   818	 *     "op": "update_link",
   819	 *     "relationshipId": "42",
   820	 *     "fromEntityId": "10",
   821	 *     "toEntityId": "11",
   822	 *     "relationshipTypeId": "3",
   823	 *     "relationshipTypeSlug": "invoice_customer",
   824	 *     "changes": [{ "field": "confidence", "old": 0.5, "new": 0.9 }]
   825	 *   }
   826	 */
   827	export function recordEdgeChangeEvent(params: EdgeChangeEventParams): void {
   828	  // Keep this stable across the retry below, while allowing a relationship
   829	  // revived by unmerge to record the same operation again later.
   830	  const originId = `edge:${params.relationshipId}:${params.op}:${crypto.randomUUID()}`;
   831	  const verb =
   832	    params.op === 'link' ? 'linked' : params.op === 'unlink' ? 'unlinked' : 'updated';
   833	
