  1	/**
  2	 * Relationship Validation Helpers
  3	 *
  4	 * Validates entity relationship constraints: self-reference, confidence bounds,
  5	 * source enums, symmetric canonicalization, scope enforcement, type-pair rules, and
  6	 * duplicate edge detection.
  7	 */
  8	
  9	import { type DbClient, getDb } from '../db/client';
 10	import { ToolUserError } from './errors';
 11	import type { Env } from '../index';
 12	import type { ToolContext } from '../tools/registry';
 13	
 14	/** Sources accepted from the manage_entity link/update_link surface. */
 15	const CALLER_SETTABLE_SOURCES = ['ui', 'llm', 'feed', 'api'] as const;
 16	
 17	export const EDGE_SOURCE_CONFIG = 'config';
 18	export const EDGE_SOURCE_MANUAL = 'manual';
 19	
 20	/** Source values used to select edges during reconciliation. */
 21	const RECONCILED_SOURCES = [EDGE_SOURCE_CONFIG, EDGE_SOURCE_MANUAL] as const;
 22	
 23	type CallerSettableSource = (typeof CALLER_SETTABLE_SOURCES)[number];
 24	
 25	/**
 26	 * Validate that a relationship does not reference itself.
 27	 */
 28	export function validateNoSelfReference(fromId: number, toId: number): void {
 29	  if (fromId === toId) {
 30	    throw new ToolUserError('Self-referencing relationships are not allowed', 400);
 31	  }
 32	}
 33	
 34	/**
 35	 * Validate confidence is in [0, 1] range.
 36	 */
 37	export function validateConfidence(confidence: number | undefined | null): void {
 38	  if (confidence === undefined || confidence === null) return;
 39	  if (typeof confidence !== 'number' || confidence < 0 || confidence > 1) {
 40	    throw new ToolUserError('Confidence must be a number between 0 and 1', 400);
 41	  }
 42	}
 43	
 44	/**
 45	 * Validate a caller-supplied source.
 46	 *
 47	 * Reconciled sources are internal: callers may neither create edges in a
 48	 * reconciler's scope nor move existing edges into it.
 49	 */
 50	export function validateSource(source: string | undefined | null): void {
 51	  if (source === undefined || source === null) return;
 52	  if (!CALLER_SETTABLE_SOURCES.includes(source as CallerSettableSource)) {
 53	    throw new ToolUserError(
 54	      `Invalid source "${source}". Must be one of: ${CALLER_SETTABLE_SOURCES.join(', ')}`,
 55	      400
 56	    );
 57	  }
 58	}
 59	
 60	/**
 61	 * Refuse to change the source or metadata that identify a reconciled edge.
 62	 */
 63	export function validateReconciledEdgeUpdate(
 64	  current: string | null | undefined,
 65	  next: string | undefined | null,
 66	  metadataChanged: boolean
 67	): void {
 68	  if (!RECONCILED_SOURCES.includes(current as (typeof RECONCILED_SOURCES)[number])) {
 69	    return;
 70	  }
 71	  if ((next === undefined || next === null) && !metadataChanged) return;
 72	  throw new ToolUserError(
 73	    `Cannot change source or metadata of a "${current}"-owned relationship. It is reconciled by the subsystem that created it; edit that configuration instead.`,
 74	    400
 75	  );
 76	}
 77	
 78	/**
 79	 * Canonicalize a symmetric edge so from_entity_id < to_entity_id.
 80	 */
 81	export function canonicalizeSymmetricEdge(
 82	  fromId: number,
 83	  toId: number
 84	): { from: number; to: number } {
 85	  return fromId <= toId ? { from: fromId, to: toId } : { from: toId, to: fromId };
 86	}
 87	
 88	/**
 89	 * Validate scope rule for a relationship.
 90	 *
 91	 * The from_entity must belong to the caller's organization (relationships are
 92	 * always authored from the source's org). The to_entity may be either in the
 93	 * same org or in a public-catalog org (`organization.visibility='public'`),
 94	 * which lets a tenant's relationship reference canonical world entities like
 95	 * HMRC or Barclays without copying them locally.
 96	 *
 97	 * Public → tenant references are forbidden — public catalogs never reach into
 98	 * private orgs. The relationship row's organization_id always matches the
 99	 * source's org (the caller's), keeping the assertion under the caller's
100	 * delete/visibility control.
101	 */
102	export async function validateScopeRule(
103	  fromEntityId: number,
104	  toEntityId: number,
105	  _env: Env,
106	  ctx: ToolContext
107	): Promise<void> {
108	  const sql = getDb();
109	
110	  const rows = await sql`
111	    SELECT e.id, e.organization_id, o.visibility
112	    FROM entities e
113	    LEFT JOIN organization o ON o.id = e.organization_id
114	    WHERE e.id IN (${fromEntityId}, ${toEntityId})
115	  `;
116	
117	  if (rows.length < 2) {
118	    const foundIds = rows.map((r) => r.id);
119	    const missingId = [fromEntityId, toEntityId].find((id) => !foundIds.includes(id));
120	    throw new ToolUserError(`Entity ${missingId} not found`, 404);
121	  }
122	
123	  const fromEntity = rows.find((r) => Number(r.id) === fromEntityId)!;
124	  const toEntity = rows.find((r) => Number(r.id) === toEntityId)!;
125	
126	  // Source must always be in the caller's org — you can't author relationships
127	  // *from* someone else's entity.
128	  if (String(fromEntity.organization_id) !== ctx.organizationId) {
129	    throw new ToolUserError(`Entity ${fromEntityId} does not belong to your organization`, 403);
130	  }
131	
132	  // Target may be same-org OR a public-catalog entity. Anything else (a
133	  // private org you don't control) is rejected.
134	  const toOrgId = String(toEntity.organization_id);
135	  const toVisibility = String(toEntity.visibility ?? 'private');
136	  if (toOrgId !== ctx.organizationId && toVisibility !== 'public') {
137	    throw new ToolUserError(
138	      `Entity ${toEntityId} is in a private organization that does not belong to you. Cross-org references are only allowed to entities in public catalogs.`,
139	      403
140	    );
141	  }
142	}
143	
144	/**
145	 * Validate that the relationship type allows the given entity type pair.
146	 * For symmetric types, checks both directions.
147	 */
148	export async function validateTypeRule(
149	  relationshipTypeId: number,
150	  fromEntityId: number,
151	  toEntityId: number,
152	  sql: DbClient
153	): Promise<void> {
154	  // Get the relationship type to check if it's symmetric
155	  const typeRows = await sql`
156	    SELECT is_symmetric
157	    FROM entity_relationship_types
158	    WHERE id = ${relationshipTypeId}
159	      AND deleted_at IS NULL
160	  `;
161	  if (typeRows.length === 0) {
162	    throw new ToolUserError(`Relationship type ${relationshipTypeId} not found`, 404);
163	  }
164	  const isSymmetric = Boolean(typeRows[0].is_symmetric);
165	
166	  // Get entity types for both entities
167	  const entityRows = await sql`
168	    SELECT e.id, et.slug AS entity_type
169	    FROM entities e
170	    JOIN entity_types et ON et.id = e.entity_type_id
171	    WHERE e.id IN (${fromEntityId}, ${toEntityId})
172	  `;
173	  const fromEntityType = String(entityRows.find((r) => Number(r.id) === fromEntityId)?.entity_type);
174	  const toEntityType = String(entityRows.find((r) => Number(r.id) === toEntityId)?.entity_type);
175	
176	  // Check if there are any rules for this relationship type
177	  const ruleRows = await sql`
178	    SELECT source_entity_type_slug, target_entity_type_slug
179	    FROM entity_relationship_type_rules
180	    WHERE relationship_type_id = ${relationshipTypeId}
181	      AND deleted_at IS NULL
182	  `;
183	
184	  // No rules = any pair is allowed
185	  if (ruleRows.length === 0) return;
186	
187	  // Check if the pair matches any rule (check both directions for symmetric types)
188	  const matches = ruleRows.some((rule) => {
189	    const srcSlug = String(rule.source_entity_type_slug);
190	    const tgtSlug = String(rule.target_entity_type_slug);
191	
192	    if (srcSlug === fromEntityType && tgtSlug === toEntityType) return true;
193	    if (isSymmetric && srcSlug === toEntityType && tgtSlug === fromEntityType) return true;
194	    return false;
195	  });
196	
197	  if (!matches) {
198	    throw new ToolUserError(
199	      `Relationship type ${relationshipTypeId} does not allow ${fromEntityType} → ${toEntityType}`,
200	      400
201	    );
202	  }
203	}
