  1	/**
  2	 * NER-Lite Auto-Linker
  3	 *
  4	 * Scans event content for entity name mentions and creates
  5	 * `mentions` relationships automatically. Fire-and-forget pattern.
  6	 */
  7	
  8	import { getDb } from '../db/client';
  9	import logger from './logger';
 10	
 11	interface AutoLinkParams {
 12	  eventId: number;
 13	  entityIds: number[];
 14	  content: string;
 15	  title?: string | null;
 16	  organizationId: string;
 17	}
 18	
 19	interface EntityCandidate {
 20	  id: number;
 21	  name: string;
 22	  entity_type: string;
 23	}
 24	
 25	// Per-org entity name cache (60s TTL)
 26	const entityCache = new Map<string, { entities: EntityCandidate[]; ts: number }>();
 27	const CACHE_TTL_MS = 60_000;
 28	const MAX_CONTENT_LENGTH = 5_000;
 29	const MAX_AUTO_LINKS = 20;
 30	const MIN_NAME_LENGTH = 3;
 31	
 32	async function getOrgEntities(organizationId: string): Promise<EntityCandidate[]> {
 33	  const cached = entityCache.get(organizationId);
 34	  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) return cached.entities;
 35	
 36	  const sql = getDb();
 37	  const rows = await sql`
 38	    SELECT e.id, e.name, et.slug AS entity_type
 39	    FROM entities e
 40	    JOIN entity_types et ON et.id = e.entity_type_id
 41	    WHERE e.organization_id = ${organizationId}
 42	      AND e.deleted_at IS NULL
 43	      AND length(e.name) >= ${MIN_NAME_LENGTH}
 44	    ORDER BY length(e.name) DESC
 45	  `;
 46	
 47	  const entities = rows.map((r) => ({
 48	    id: Number(r.id),
 49	    name: r.name as string,
 50	    entity_type: r.entity_type as string,
 51	  }));
 52	
 53	  entityCache.set(organizationId, { entities, ts: Date.now() });
 54	  return entities;
 55	}
 56	
 57	async function ensureMentionsType(organizationId: string): Promise<number> {
 58	  const sql = getDb();
 59	  const rows = await sql`
 60	    INSERT INTO entity_relationship_types
 61	      (slug, name, description, organization_id, is_symmetric, created_by, created_at, updated_at)
 62	    VALUES
 63	      ('mentions', 'Mentions', 'Auto-discovered content reference', ${organizationId},
 64	       false, NULL, current_timestamp, current_timestamp)
 65	    ON CONFLICT (organization_id, slug) WHERE status = 'active'
 66	    DO UPDATE SET updated_at = EXCLUDED.updated_at
 67	    RETURNING id
 68	  `;
 69	  return Number(rows[0].id);
 70	}
 71	
 72	/**
 73	 * Scan content for entity name mentions and create relationships.
 74	 */
 75	export async function autoLinkEvent(params: AutoLinkParams): Promise<void> {
 76	  const { entityIds, content, title, organizationId } = params;
 77	  if (!content && !title) return;
 78	
 79	  const allEntities = await getOrgEntities(organizationId);
 80	  const sourceSet = new Set(entityIds);
 81	
 82	  // Combine title + content, cap length
 83	  const searchText = [title, content].filter(Boolean).join(' ').slice(0, MAX_CONTENT_LENGTH);
 84	
 85	  const matched = new Set<number>();
 86	  const candidates: { fromId: number; toId: number }[] = [];
 87	
 88	  for (const entity of allEntities) {
 89	    if (sourceSet.has(entity.id) || matched.has(entity.id)) continue;
 90	
 91	    const escaped = entity.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
 92	    const regex = new RegExp(`\\b${escaped}\\b`, 'i');
 93	
 94	    if (regex.test(searchText)) {
 95	      matched.add(entity.id);
 96	      for (const sourceId of entityIds) {
 97	        if (sourceId === entity.id) continue;
 98	        candidates.push({ fromId: sourceId, toId: entity.id });
 99	        if (candidates.length >= MAX_AUTO_LINKS) break;
100	      }
101	      if (candidates.length >= MAX_AUTO_LINKS) break;
102	    }
103	  }
104	
105	  if (candidates.length === 0) return;
106	
107	  const sql = getDb();
108	  const typeId = await ensureMentionsType(organizationId);
109	  let created = 0;
110	
111	  for (const { fromId, toId } of candidates) {
112	    const { from, to } = { from: fromId, to: toId };
113	
114	    // `mentions` is directional. Only skip when the same directional type already exists.
115	    const existing = await sql`
116	      SELECT id FROM entity_relationships
117	      WHERE from_entity_id = ${from} AND to_entity_id = ${to}
118	        AND relationship_type_id = ${typeId}
119	        AND organization_id = ${organizationId}
120	        AND deleted_at IS NULL
121	      LIMIT 1
122	    `;
123	    if (existing.length > 0) continue;
124	
125	    await sql`
126	      INSERT INTO entity_relationships (
127	        organization_id, from_entity_id, to_entity_id, relationship_type_id,
128	        confidence, source, created_by, updated_by, created_at, updated_at
129	      ) VALUES (
130	        ${organizationId}, ${from}, ${to}, ${typeId},
131	        0.4, 'feed', NULL, NULL,
132	        current_timestamp, current_timestamp
133	      )
134	    `;
135	    created++;
136	  }
137	
138	  if (created > 0) {
139	    logger.debug(
140	      { created, eventId: params.eventId, matched: matched.size },
141	      '[auto-linker] Links created'
142	    );
143	  }
144	}
