  2	
  3	-- Seed the `works_at` auto_create_when rule on every public catalog org.
  4	--
  5	-- The identity engine (packages/server/src/identity/engine.ts) derives a
  6	-- relationship edge when a person-fact's normalized value equals a catalog
  7	-- entity's `metadata->>targetField`. This migration wires the canonical
  8	-- employment inference:
  9	--
 10	--   person fact  email_domain = "acme.com"
 11	--   catalog company  metadata.domain = "acme.com"
 12	--   ⇒ derive  person --works_at--> company
 13	--
 14	-- The `email_domain` fact is derived centrally by the engine from every
 15	-- `email` fact (see deriveCompanionFacts), so this fires for any connector
 16	-- that produces an email — not just Google Workspace `hd` sign-ins.
 17	--
 18	-- Two things must be true for the engine to act (both seeded here, per
 19	-- public-catalog org that has a `company` type):
 20	--   1. `company.domain` is declared `x-identity-namespace: true` in the type's
 21	--      metadata_schema — engine.ts:findEntitiesByMetadataField refuses to match
 22	--      an undeclared field.
 23	--   2. an active `works_at` relationship type carries the compiled rule blob
 24	--      { autoCreateWhen, ruleVersion, ruleHash } in `metadata`.
 25	--
 26	-- ruleHash below is sha256 of the canonicalised rule set, matching
 27	-- ruleHashFor() in packages/server/src/identity/rules.ts. It is validated at
 28	-- read time by loadRules(): if this hash ever disagrees with a fresh hash of
 29	-- the stored rules (e.g. the canonicaliser changes), the engine SKIPS the rule
 30	-- and logs drift rather than acting on a stale rule — so a mistake here fails
 31	-- safe (no derivations), never wrong. If the rule set is edited, recompute the
 32	-- hash with ruleHashFor and reseed.
 33	--
 34	-- assuranceRequired = 'oauth_verified': only provider-verified emails derive an
 35	-- edge. A self-attested or scraped contact email will not create a works_at,
 36	-- and a personal @gmail.com never matches a company (gmail.com is not a
 37	-- company domain), so false "works at Google" edges are avoided by design.
 38	--
 39	-- matchStrategy = 'unique_only': if two catalog companies share a domain the
 40	-- engine records a collision event for human resolution instead of guessing.
 41	
 42	DO $$
 43	DECLARE
 44	  org RECORD;
 45	  company_type RECORD;
 46	  schema jsonb;
 47	  props jsonb;
 48	  domain_prop jsonb;
 49	  rule_metadata jsonb;
 50	BEGIN
 51	  rule_metadata := jsonb_build_object(
 52	    'autoCreateWhen', jsonb_build_array(
 53	      jsonb_build_object(
 54	        'sourceNamespace', 'email_domain',
 55	        'targetField', 'domain',
 56	        'assuranceRequired', 'oauth_verified',
 57	        'matchStrategy', 'unique_only'
 58	      )
 59	    ),
 60	    'ruleVersion', 1,
 61	    'ruleHash', 'db3256f51ec866accb213b0167068f2f4df32e55b4bd5eb83067d27a157c7419'
 62	  );
 63	
 64	  FOR org IN
 65	    SELECT id FROM organization WHERE visibility = 'public'
 66	  LOOP
 67	    -- Only orgs that actually model companies get the rule/field.
 68	    SELECT id, metadata_schema INTO company_type
 69	    FROM entity_types
 70	    WHERE organization_id = org.id
 71	      AND slug = 'company'
 72	      AND deleted_at IS NULL
 73	    LIMIT 1;
 74	
 75	    IF NOT FOUND THEN
 76	      CONTINUE;
 77	    END IF;
 78	
 79	    -- 1. Declare company.domain as an identity-matchable field, preserving any
 80	    --    existing schema/props. Only ADD the marker when it is absent — an
 81	    --    existing x-identity-namespace value (true OR the richer object form the
 82	    --    engine also accepts) is left untouched, so a reseed never downgrades a
 83	    --    hand-tuned declaration. Idempotent: with the marker present this is a
 84	    --    no-op on that key.
 85	    schema := COALESCE(company_type.metadata_schema, '{"type":"object"}'::jsonb);
 86	    props := COALESCE(schema -> 'properties', '{}'::jsonb);
 87	    domain_prop := COALESCE(props -> 'domain', '{"type":"string"}'::jsonb);
 88	    IF NOT (domain_prop ? 'x-identity-namespace') THEN
 89	      domain_prop := domain_prop || '{"x-identity-namespace": true}'::jsonb;
 90	      props := props || jsonb_build_object('domain', domain_prop);
 91	      schema := schema || jsonb_build_object('properties', props);
 92	      UPDATE entity_types
 93	      SET metadata_schema = schema, updated_at = now()
 94	      WHERE id = company_type.id;
 95	    END IF;
 96	
 97	    -- 2. Upsert the works_at type carrying the compiled rule. Idempotent on the
 98	    --    active (organization_id, slug) unique index; on conflict we MERGE the
 99	    --    rule keys into any existing metadata (never clobber other fields on an
100	    --    already-defined works_at type) so a reseed corrects drift in place.
101	    INSERT INTO entity_relationship_types (
102	      organization_id, slug, name, description, is_symmetric, status, metadata,
103	      created_at, updated_at
104	    ) VALUES (
105	      org.id, 'works_at', 'Works at',
106	      'Person is employed by / affiliated with a company. Auto-derived when the person''s email domain matches the company''s domain.',
107	      false, 'active', rule_metadata, now(), now()
108	    )
109	    ON CONFLICT (organization_id, slug) WHERE (status = 'active')
110	    DO UPDATE SET
111	      metadata = COALESCE(entity_relationship_types.metadata, '{}'::jsonb) || rule_metadata,
112	      updated_at = now();
113	  END LOOP;
114	END $$;
115	
116	-- migrate:down
117	
118	-- Remove the seeded rule; leave the x-identity-namespace marker on
119	-- company.domain in place (harmless without a rule, and other rules may rely
120	-- on it). Only strip the works_at rule metadata we added.
121	DO $$
122	DECLARE
123	  org RECORD;
124	BEGIN
125	  FOR org IN
126	    SELECT id FROM organization WHERE visibility = 'public'
127	  LOOP
128	    UPDATE entity_relationship_types
129	    SET metadata = metadata - 'autoCreateWhen' - 'ruleVersion' - 'ruleHash',
130	        updated_at = now()
131	    WHERE organization_id = org.id
132	      AND slug = 'works_at'
133	      AND status = 'active'
134	      AND metadata ->> 'ruleHash' = 'db3256f51ec866accb213b0167068f2f4df32e55b4bd5eb83067d27a157c7419';
135	  END LOOP;
136	END $$;

